import{_ as a,a as t}from"./chunks/fixedwing_dtrim.CBgAydAV.js";import{_ as i,o as r,c as o,al as n}from"./chunks/framework.7vp1BMOE.js";const g=JSON.parse('{"title":"固定翼配平指南","description":"","frontmatter":{},"headers":[],"relativePath":"zh/config_fw/trimming_guide_fixedwing.md","filePath":"zh/config_fw/trimming_guide_fixedwing.md"}'),c={name:"zh/config_fw/trimming_guide_fixedwing.md"};function l(d,e,s,h,_,f){return r(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="固定翼配平指南" tabindex="-1">固定翼配平指南 <a class="header-anchor" href="#固定翼配平指南" aria-label="Permalink to &quot;固定翼配平指南&quot;">​</a></h1><p>配平校准是指在配平状态下计算/设置舵面偏度（配平状态包含相对空速、空气密度、攻击角、飞机配置等）。一架具有合适配平设置的飞机在配平状态下飞行将自动保持其姿态，不需要飞行员或增稳计算机进行任何的控制操作。</p><p>General aviation, commercial and large unmanned planes trim their control surfaces using <a href="https://en.wikipedia.org/wiki/Trim_tab" target="_blank" rel="noreferrer">trim tabs</a> while small UAVs simply add an offset to the actuator of the control surface.</p><p>The <a href="#basic-trimming">Basic trimming</a> section explains the purpose of each trim parameter and how to find the correct value. The <a href="#advanced-trimming">Advanced Trimming</a> section introduces parameters that can be set to automatically adjust the trims based on the measured airspeed and flap position.</p><h2 id="基础配平" tabindex="-1">基础配平 <a class="header-anchor" href="#基础配平" aria-label="Permalink to &quot;基础配平&quot;">​</a></h2><p>操作者可通过若干个参数来恰当地配平固定翼飞机。以下是这些参数及其使用场景的概述：</p><ul><li><a href="./../advanced_config/parameter_reference#RC1_TRIM">RCx_TRIM</a> applies trim to the signal received from the RC transmitter. These parameters are set automatically during <a href="./../config/radio">RC calibration</a>.</li><li><a href="./../advanced_config/parameter_reference#CA_SV_CS0_TRIM">CA_SV_CSx_TRIM</a> applies trim to a control surfaces channel. 该参数用于在飞行前精确地将舵面与默认角度对齐。</li><li><a href="./../advanced_config/parameter_reference#FW_PSP_OFF">FW_PSP_OFF</a> is the pitch angle at which your aircraft flies level at trim airspeed. See <a href="#level-flight-pitch">Level-Flight Pitch</a> for how PX4 defines and uses it.</li><li><a href="./../advanced_config/parameter_reference#FW_AIRSPD_TRIM">FW_AIRSPD_TRIM</a> is used by the rate controllers to scale their output depending on the measured airspeed. See <a href="./../flight_stack/controller_diagrams#airspeed-scaling">Airspeed Scaling</a> for more details.</li><li><a href="./../advanced_config/parameter_reference#TRIM_ROLL">TRIM_ROLL</a>, <a href="./../advanced_config/parameter_reference#TRIM_PITCH">TRIM_PITCH</a> and <a href="./../advanced_config/parameter_reference#TRIM_YAW">TRIM_YAW</a> apply trim to the control signals <em>before</em> mixing. For example, if you have two servos for the elevator, <code>TRIM_PITCH</code> applies trim to both of them. 这些参数在您的舵面已对齐，但在手动飞行期间出现飞机俯仰/滚轮/偏航/上下/左右动作(不稳定)时，或在增稳飞行期间控制信号有恒定偏移时使用。</li></ul><p>设置上述参数的正确顺序是：</p><ol><li>Trim the servos by physically adjusting the linkages lengths if possible and fine tune by trimming the PWM channels (use <code>PWM_MAIN/AUX_TRIMx</code>) on the bench to properly set the control surfaces to their theoretical position.</li><li>Fly in stabilized mode at cruise speed and set <code>FW_PSP_OFF</code> to the pitch angle that the airplane needs to fly at in order to keep constant altitude during wing-leveled flight. If you are using an airspeed sensor, also set the correct cruise airspeed (<code>FW_AIRSPD_TRIM</code>).</li><li>Look at the actuator controls in the log file (upload it to <a href="https://logs.px4.io" target="_blank" rel="noreferrer">Flight Review</a> and check the <em>Actuator Controls</em> plot for example) and set the pitch trim (<code>TRIM_PITCH</code>). 将该值设置为平飞时俯仰角度的平均值。</li></ol><p>步骤3可以在步骤2之前执行，如果你不想查看日志， 或者如果您在手动模式下感觉舒适。 You can then trim your remote (with the trim switches) and report the values to <code>TRIM_PITCH</code> (and remove the trims from your transmitter) or update <code>TRIM_PITCH</code> directly during flight via telemetry and QGC.</p><h2 id="level-flight-pitch" tabindex="-1">Level-Flight Pitch <a class="header-anchor" href="#level-flight-pitch" aria-label="Permalink to &quot;Level-Flight Pitch&quot;">​</a></h2><p>PX4 measures the fixed-wing pitch angle θ between the body x-axis and the horizon. The body frame is fixed to the vehicle: x points forward through the nose, y along the right wing and z down. Its orientation follows the mounting of the flight controller (see <a href="./../config/flight_controller_orientation">Flight Controller Orientation</a>), not the wing chord. For tailsitters, the fixed-wing body frame is the multicopter body frame rotated by 90° in pitch.</p><p><img src="'+a+'" alt="Side view of a fixed-wing aircraft pitched up: the body x-axis points forward, z down and y along the right wing out of the page; the pitch angle θ is the angle between the body x-axis and the horizon, and in level flight at trim airspeed it equals FW_PSP_OFF"></p><p><a href="./../advanced_config/parameter_reference#FW_PSP_OFF">FW_PSP_OFF</a> is θ in level flight at trim airspeed (<a href="./../advanced_config/parameter_reference#FW_AIRSPD_TRIM">FW_AIRSPD_TRIM</a>). In level flight the velocity is horizontal, so this is also the angle of attack measured from the body x-axis. It differs from the angle of attack of the wing by the angle between the wing chord and the body x-axis.</p><p>Pitch setpoints and pitch limits in PX4 are absolute pitch angles θ, and <code>FW_PSP_OFF</code> is not added to them. This applies for example to <a href="./../advanced_config/parameter_reference#FW_P_LIM_MIN">FW_P_LIM_MIN</a>, <a href="./../advanced_config/parameter_reference#FW_P_LIM_MAX">FW_P_LIM_MAX</a>, <a href="./../advanced_config/parameter_reference#FW_TKO_PITCH_MIN">FW_TKO_PITCH_MIN</a>, <a href="./../advanced_config/parameter_reference#FW_LND_FL_PMIN">FW_LND_FL_PMIN</a>, <a href="./../advanced_config/parameter_reference#FW_LND_FL_PMAX">FW_LND_FL_PMAX</a> and <a href="./../advanced_config/parameter_reference#RWTO_PSP">RWTO_PSP</a>.</p><p><code>FW_PSP_OFF</code> itself is used in these places:</p><ul><li>The altitude and airspeed controller (TECS) uses <code>FW_PSP_OFF</code> as the pitch at zero climb angle: its pitch setpoint is <code>FW_PSP_OFF</code> plus the commanded climb angle plus an integrator correction. The logged TECS pitch setpoint (<code>tecs_status.pitch_sp_rad</code>) is absolute, while the logged pitch integrator (<code>tecs_status.pitch_integ</code>) is a correction added to it rather than a pitch angle.</li><li>In <a href="./../flight_modes_fw/stabilized">Stabilized mode</a>, the centred pitch stick commands <code>FW_PSP_OFF</code>.</li><li>During the front transition, standard VTOLs ramp their pitch setpoint to <code>FW_PSP_OFF</code>, and tailsitters end their pitch-down rotation at it.</li><li>The first principle check of the <a href="./../advanced_config/airspeed_validation">airspeed validation</a> considers the vehicle to be pitching down when θ is below <code>FW_PSP_OFF</code>.</li></ul><h2 id="高级配平" tabindex="-1">高级配平 <a class="header-anchor" href="#高级配平" aria-label="Permalink to &quot;高级配平&quot;">​</a></h2><p>在空速增加过程中，会因非对称翼型和使用襟翼而引入俯仰通道低头力矩，因此飞机需要根据测量空速和襟翼位置重新计算配平。为此，可以使用以下参数定义一个关于空速的双线性曲线函数和关于襟翼状态的俯仰修正增量函数（参见下图）：</p><ul><li><a href="./../advanced_config/parameter_reference#FW_DTRIM_R_VMIN">FW_DTRIM_[R/P/Y]_[VMIN/VMAX]</a> are the roll/pitch/yaw trim value added to <code>TRIM_ROLL/PITCH/YAW</code> at min/max airspeed (defined by <a href="./../advanced_config/parameter_reference#FW_AIRSPD_MIN">FW_AIRSPD_MIN</a> and <a href="./../advanced_config/parameter_reference#FW_AIRSPD_MAX">FW_AIRSPD_MAX</a>).</li><li><a href="./../advanced_config/parameter_reference#CA_SV_CS0_FLAP">CA_SV_CSx_FLAP</a> and <a href="./../advanced_config/parameter_reference#CA_SV_CS0_SPOIL">CA_SV_CSx_SPOIL</a> are the trimming values that are applied to these control surfaces if the flaps or the spoilers are fully deployed, respectively.</li></ul><p><img src="'+t+'" alt="Dtrim Curve"></p><p>A perfectly symmetrical airframe would only require pitch trim increments, but since a real airframe is never perfectly symmetrical, roll and yaw trims increments are also sometimes required.</p>',22)])])}const u=i(c,[["render",l]]);export{g as __pageData,u as default};
